def opening_entries(apps, schema_editor):
    Wallet = apps.get_model("wallet", "Wallet")
    Entry = apps.get_model("wallet", "WalletEntry")
    now = django.utils.timezone.now()
    for wallet in Wallet.objects.using(schema_editor.connection.alias).all().iterator():
        wallet.history_started_at = now
        wallet.save(update_fields=["history_started_at"])
        if wallet.current_earnings:
            Entry.objects.using(schema_editor.connection.alias).create(
                wallet=wallet,
                reference=f"opening:{wallet.pk}",
                description="Opening balance at ledger migration",
                type="adjustment",
                status="completed",
                amount=wallet.current_earnings,
                created_at=now,
                completed_at=now,
            )


